  5033  static void
  5034  tune_call2_call(Node* node)
  5035  {
  5036    switch (NODE_TYPE(node)) {
  5037    case NODE_LIST:
  5038    case NODE_ALT:
  5039      do {
  5040        tune_call2_call(NODE_CAR(node));
  5041      } while (IS_NOT_NULL(node = NODE_CDR(node)));
  5042      break;
  5043
  5044    case NODE_QUANT:
  5045      tune_call2_call(NODE_BODY(node));
  5046      break;
  5047
  5048    case NODE_ANCHOR:
  5049      if (ANCHOR_HAS_BODY(ANCHOR_(node)))
  5050        tune_call2_call(NODE_BODY(node));
  5051      break;
  5052
  5053    case NODE_BAG:
  5054      {
  5055        BagNode* en = BAG_(node);
  5056
  5057        if (en->type == BAG_MEMORY) {
  5058          if (! NODE_IS_MARK1(node)) {
  5059            NODE_STATUS_ADD(node, MARK1);
  5060            tune_call2_call(NODE_BODY(node));
  5061            NODE_STATUS_REMOVE(node, MARK1);
  5062          }
  5063        }
  5064        else if (en->type == BAG_IF_ELSE) {
  5065          tune_call2_call(NODE_BODY(node));
  5066          if (IS_NOT_NULL(en->te.Then))
  5067            tune_call2_call(en->te.Then);
  5068          if (IS_NOT_NULL(en->te.Else))
  5069            tune_call2_call(en->te.Else);
  5070        }
  5071        else {
  5072          tune_call2_call(NODE_BODY(node));
  5073        }
  5074      }
  5075      break;
  5076
  5077    case NODE_CALL:
  5078      if (! NODE_IS_MARK1(node)) {
  5079        NODE_STATUS_ADD(node, MARK1);
  5080        {
  5081          CallNode* cn = CALL_(node);
  5082          Node* called = NODE_CALL_BODY(cn);
  5083
  5084          cn->entry_count++;
  5085
  5086          NODE_STATUS_ADD(called, CALLED);
  5087          BAG_(called)->m.entry_count++;
  5088          tune_call2_call(called);
  5089        }
  5090        NODE_STATUS_REMOVE(node, MARK1);
  5091      }
  5092      break;
  5093
  5094    default:
  5095      break;
  5096    }
  5097  }
