  5099  static int
  5100  tune_call(Node* node, ScanEnv* env, int state)
  5101  {
  5102    int r;
  5103
  5104    switch (NODE_TYPE(node)) {
  5105    case NODE_LIST:
  5106    case NODE_ALT:
  5107      do {
  5108        r = tune_call(NODE_CAR(node), env, state);
  5109      } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  5110      break;
  5111
  5112    case NODE_QUANT:
  5113      if (QUANT_(node)->upper == 0)
  5114        state |= IN_ZERO_REPEAT;
  5115
  5116      r = tune_call(NODE_BODY(node), env, state);
  5117      break;
  5118
  5119    case NODE_ANCHOR:
  5120      if (ANCHOR_HAS_BODY(ANCHOR_(node)))
  5121        r = tune_call(NODE_BODY(node), env, state);
  5122      else
  5123        r = 0;
  5124      break;
  5125
  5126    case NODE_BAG:
  5127      {
  5128        BagNode* en = BAG_(node);
  5129
  5130        if (en->type == BAG_MEMORY) {
  5131          if ((state & IN_ZERO_REPEAT) != 0) {
  5132            NODE_STATUS_ADD(node, IN_ZERO_REPEAT);
  5133            BAG_(node)->m.entry_count--;
  5134          }
  5135          r = tune_call(NODE_BODY(node), env, state);
  5136        }
  5137        else if (en->type == BAG_IF_ELSE) {
  5138          r = tune_call(NODE_BODY(node), env, state);
  5139          if (r != 0) return r;
  5140          if (IS_NOT_NULL(en->te.Then)) {
  5141            r = tune_call(en->te.Then, env, state);
  5142            if (r != 0) return r;
  5143          }
  5144          if (IS_NOT_NULL(en->te.Else))
  5145            r = tune_call(en->te.Else, env, state);
  5146        }
  5147        else
  5148          r = tune_call(NODE_BODY(node), env, state);
  5149      }
  5150      break;
  5151
  5152    case NODE_CALL:
  5153      if ((state & IN_ZERO_REPEAT) != 0) {
  5154        NODE_STATUS_ADD(node, IN_ZERO_REPEAT);
  5155        CALL_(node)->entry_count--;
  5156      }
  5157
  5158      r = tune_call_node_call(CALL_(node), env, state);
  5159      break;
  5160
  5161    default:
  5162      r = 0;
  5163      break;
  5164    }
  5165
  5166    return r;
  5167  }
