  5170  tune_call2(Node* node)
  5171  {
  5172    int r = 0;
  5173
  5174    switch (NODE_TYPE(node)) {
  5175    case NODE_LIST:
  5176    case NODE_ALT:
  5177      do {
  5178        r = tune_call2(NODE_CAR(node));
  5179      } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  5180      break;
  5181
  5182    case NODE_QUANT:
  5183      if (QUANT_(node)->upper != 0)
  5184        r = tune_call2(NODE_BODY(node));
  5185      break;
  5186
  5187    case NODE_ANCHOR:
  5188      if (ANCHOR_HAS_BODY(ANCHOR_(node)))
  5189        r = tune_call2(NODE_BODY(node));
  5190      break;
  5191
  5192    case NODE_BAG:
  5193      if (! NODE_IS_IN_ZERO_REPEAT(node))
  5194        r = tune_call2(NODE_BODY(node));
  5195
  5196      {
  5197        BagNode* en = BAG_(node);
  5198
  5199        if (r != 0) return r;
  5200        if (en->type == BAG_IF_ELSE) {
  5201          if (IS_NOT_NULL(en->te.Then)) {
  5202            r = tune_call2(en->te.Then);
  5203            if (r != 0) return r;
  5204          }
  5205          if (IS_NOT_NULL(en->te.Else))
  5206            r = tune_call2(en->te.Else);
  5207        }
  5208      }
  5209      break;
  5210
  5211    case NODE_CALL:
  5212      if (! NODE_IS_IN_ZERO_REPEAT(node)) {
  5213        tune_call2_call(node);
  5214      }
  5215      break;
  5216
  5217    default:
  5218      break;
  5219    }
  5220
  5221    return r;
  5222  }
