  5225  static void
  5226  tune_called_state_call(Node* node, int state)
  5227  {
  5228    switch (NODE_TYPE(node)) {
  5229    case NODE_ALT:
  5230      state |= IN_ALT;
  5231      /* fall */
  5232    case NODE_LIST:
  5233      do {
  5234        tune_called_state_call(NODE_CAR(node), state);
  5235      } while (IS_NOT_NULL(node = NODE_CDR(node)));
  5236      break;
  5237
  5238    case NODE_QUANT:
  5239      {
  5240        QuantNode* qn = QUANT_(node);
  5241
  5242        if (IS_INFINITE_REPEAT(qn->upper) || qn->upper >= 2)
  5243          state |= IN_REAL_REPEAT;
  5244        if (qn->lower != qn->upper)
  5245          state |= IN_VAR_REPEAT;
  5246
  5247        tune_called_state_call(NODE_QUANT_BODY(qn), state);
  5248      }
  5249      break;
  5250
  5251    case NODE_ANCHOR:
  5252      {
  5253        AnchorNode* an = ANCHOR_(node);
  5254
  5255        switch (an->type) {
  5256        case ANCR_PREC_READ_NOT:
  5257        case ANCR_LOOK_BEHIND_NOT:
  5258          state |= IN_NOT;
  5259          /* fall */
  5260        case ANCR_PREC_READ:
  5261        case ANCR_LOOK_BEHIND:
  5262          tune_called_state_call(NODE_ANCHOR_BODY(an), state);
  5263          break;
  5264        default:
  5265          break;
  5266        }
  5267      }
  5268      break;
  5269
  5270    case NODE_BAG:
  5271      {
  5272        BagNode* en = BAG_(node);
  5273
  5274        if (en->type == BAG_MEMORY) {
  5275          if (NODE_IS_MARK1(node)) {
  5276            if ((~en->m.called_state & state) != 0) {
  5277              en->m.called_state |= state;
  5278              tune_called_state_call(NODE_BODY(node), state);
  5279            }
  5280          }
  5281          else {
  5282            NODE_STATUS_ADD(node, MARK1);
  5283            en->m.called_state |= state;
  5284            tune_called_state_call(NODE_BODY(node), state);
  5285            NODE_STATUS_REMOVE(node, MARK1);
  5286          }
  5287        }
  5288        else if (en->type == BAG_IF_ELSE) {
  5289          state |= IN_ALT;
  5290          tune_called_state_call(NODE_BODY(node), state);
  5291          if (IS_NOT_NULL(en->te.Then)) {
  5292            tune_called_state_call(en->te.Then, state);
  5293          }
  5294          if (IS_NOT_NULL(en->te.Else))
  5295            tune_called_state_call(en->te.Else, state);
  5296        }
  5297        else {
  5298          tune_called_state_call(NODE_BODY(node), state);
  5299        }
  5300      }
  5301      break;
  5302
  5303    case NODE_CALL:
  5304      tune_called_state_call(NODE_BODY(node), state);
  5305      break;
  5306
  5307    default:
  5308      break;
  5309    }
  5310  }
