  5441  tune_quant(Node* node, regex_t* reg, int state, ScanEnv* env)
  5442  {
  5443    int r;
  5444    QuantNode* qn = QUANT_(node);
  5445    Node* body = NODE_BODY(node);
  5446
  5447    if ((state & IN_REAL_REPEAT) != 0) {
  5448      NODE_STATUS_ADD(node, IN_REAL_REPEAT);
  5449    }
  5450    if ((state & IN_MULTI_ENTRY) != 0) {
  5451      NODE_STATUS_ADD(node, IN_MULTI_ENTRY);
  5452    }
  5453
  5454    if (IS_INFINITE_REPEAT(qn->upper) || qn->upper >= 1) {
  5455      OnigLen d = node_min_byte_len(body, env);
  5456      if (d == 0) {
  5457  #ifdef USE_STUBBORN_CHECK_CAPTURES_IN_EMPTY_REPEAT
  5458        qn->emptiness = quantifiers_memory_node_info(body);
  5459  #else
  5460        qn->emptiness = BODY_MAY_BE_EMPTY;
  5461  #endif
  5462      }
  5463    }
  5464
  5465    if (IS_INFINITE_REPEAT(qn->upper) || qn->upper >= 2)
  5466      state |= IN_REAL_REPEAT;
  5467    if (qn->lower != qn->upper)
  5468      state |= IN_VAR_REPEAT;
  5469
  5470    r = tune_tree(body, reg, state, env);
  5471    if (r != 0) return r;
  5472
  5473    /* expand string */
  5474  #define EXPAND_STRING_MAX_LENGTH  100
  5475    if (NODE_TYPE(body) == NODE_STRING) {
  5476      if (!IS_INFINITE_REPEAT(qn->lower) && qn->lower == qn->upper &&
  5477          qn->lower > 1 && qn->lower <= EXPAND_STRING_MAX_LENGTH) {
  5478        int len = NODE_STRING_LEN(body);
  5479
  5480        if (len * qn->lower <= EXPAND_STRING_MAX_LENGTH) {
  5481          int i, n = qn->lower;
  5482          node_conv_to_str_node(node, body);
  5483          for (i = 0; i < n; i++) {
  5484            r = node_str_node_cat(node, body);
  5485            if (r != 0) return r;
  5486          }
  5487          onig_node_free(body);
  5488          return r;
  5489        }
  5490      }
  5491    }
  5492
  5493    if (qn->greedy && (qn->emptiness == BODY_IS_NOT_EMPTY)) {
  5494      if (NODE_TYPE(body) == NODE_QUANT) {
  5495        QuantNode* tqn = QUANT_(body);
  5496        if (IS_NOT_NULL(tqn->head_exact)) {
  5497          qn->head_exact  = tqn->head_exact;
  5498          tqn->head_exact = NULL;
  5499        }
  5500      }
  5501      else {
  5502        qn->head_exact = get_head_value_node(NODE_BODY(node), 1, reg);
  5503      }
  5504    }
  5505
  5506    return r;
  5507  }
  5508
  5509  /* tune_tree does the following work.
  5510   1. check empty loop. (set qn->emptiness)
  5511   2. expand ignore-case in char class.
  5512   3. set memory status bit flags. (reg->mem_stats)
  5513   4. set qn->head_exact for [push, exact] -> [push_or_jump_exact1, exact].
  5514   5. find invalid patterns in look-behind.
  5515   6. expand repeated string.
  5516   */
  5517  static int
  5518  tune_tree(Node* node, regex_t* reg, int state, ScanEnv* env)
  5519  {
  5520    int r = 0;
  5521
  5522    switch (NODE_TYPE(node)) {
  5523    case NODE_LIST:
  5524      {
  5525        Node* prev = NULL_NODE;
  5526        do {
  5527          r = tune_tree(NODE_CAR(node), reg, state, env);
  5528          if (IS_NOT_NULL(prev) && r == 0) {
  5529            r = tune_next(prev, NODE_CAR(node), reg);
  5530          }
  5531          prev = NODE_CAR(node);
  5532        } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  5533      }
  5534      break;
  5535
  5536    case NODE_ALT:
  5537      do {
  5538        r = tune_tree(NODE_CAR(node), reg, (state | IN_ALT), env);
  5539      } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  5540      break;
  5541
  5542    case NODE_STRING:
  5543      if (NODE_IS_IGNORECASE(node) && ! NODE_STRING_IS_CRUDE(node)) {
  5544        r = unravel_case_fold_string(node, reg, state);
  5545      }
  5546      break;
  5547
  5548    case NODE_BACKREF:
  5549      {
  5550        int i;
  5551        int* p;
  5552        BackRefNode* br = BACKREF_(node);
  5553        p = BACKREFS_P(br);
  5554        for (i = 0; i < br->back_num; i++) {
  5555          if (p[i] > env->num_mem)  return ONIGERR_INVALID_BACKREF;
  5556          MEM_STATUS_ON(env->backrefed_mem, p[i]);
  5557  #if 0
  5558  #ifdef USE_BACKREF_WITH_LEVEL
  5559          if (NODE_IS_NEST_LEVEL(node)) {
  5560            MEM_STATUS_ON(env->backtrack_mem, p[i]);
  5561          }
  5562  #endif
  5563  #else
  5564          /* More precisely, it should be checked whether alt/repeat exists before
  5565             the subject capture node, and then this backreference position
  5566             exists before (or in) the capture node. */
  5567          MEM_STATUS_ON(env->backtrack_mem, p[i]);
  5568  #endif
  5569        }
  5570      }
  5571      break;
  5572
  5573    case NODE_BAG:
  5574      {
  5575        BagNode* en = BAG_(node);
  5576
  5577        switch (en->type) {
  5578        case BAG_OPTION:
  5579          {
  5580            OnigOptionType options = reg->options;
  5581            reg->options = BAG_(node)->o.options;
  5582            r = tune_tree(NODE_BODY(node), reg, state, env);
  5583            reg->options = options;
  5584          }
  5585          break;
  5586
  5587        case BAG_MEMORY:
  5588  #ifdef USE_CALL
  5589          state |= en->m.called_state;
  5590  #endif
  5591
  5592          if ((state & (IN_ALT | IN_NOT | IN_VAR_REPEAT | IN_MULTI_ENTRY)) != 0
  5593              || NODE_IS_RECURSION(node)) {
  5594            MEM_STATUS_ON(env->backtrack_mem, en->m.regnum);
  5595          }
  5596          r = tune_tree(NODE_BODY(node), reg, state, env);
  5597          break;
  5598
  5599        case BAG_STOP_BACKTRACK:
  5600          {
  5601            Node* target = NODE_BODY(node);
  5602            r = tune_tree(target, reg, state, env);
  5603            if (NODE_TYPE(target) == NODE_QUANT) {
  5604              QuantNode* tqn = QUANT_(target);
  5605              if (IS_INFINITE_REPEAT(tqn->upper) && tqn->lower <= 1 &&
  5606                  tqn->greedy != 0) {  /* (?>a*), a*+ etc... */
  5607                if (is_strict_real_node(NODE_BODY(target)))
  5608                  NODE_STATUS_ADD(node, STRICT_REAL_REPEAT);
  5609              }
  5610            }
  5611          }
  5612          break;
  5613
  5614        case BAG_IF_ELSE:
  5615          r = tune_tree(NODE_BODY(node), reg, (state | IN_ALT), env);
  5616          if (r != 0) return r;
  5617          if (IS_NOT_NULL(en->te.Then)) {
  5618            r = tune_tree(en->te.Then, reg, (state | IN_ALT), env);
  5619            if (r != 0) return r;
  5620          }
  5621          if (IS_NOT_NULL(en->te.Else))
  5622            r = tune_tree(en->te.Else, reg, (state | IN_ALT), env);
  5623          break;
  5624        }
  5625      }
  5626      break;
  5627
  5628    case NODE_QUANT:
  5629      r = tune_quant(node, reg, state, env);
  5630      break;
  5631
  5632    case NODE_ANCHOR:
  5633      r = tune_anchor(node, reg, state, env);
  5634      break;
  5635
  5636  #ifdef USE_CALL
  5637    case NODE_CALL:
  5638  #endif
  5639    case NODE_CTYPE:
  5640    case NODE_CCLASS:
  5641    case NODE_GIMMICK:
  5642    default:
  5643      break;
  5644    }
  5645
  5646    return r;
  5647  }
